begin;
-- Run in a disposable local transaction. No real provider calls or records.
create extension if not exists pgtap with schema extensions;select extensions.no_plan();
alter table auth.users disable trigger on_auth_user_created;
insert into auth.users(id,email) values ('ca100000-0000-4000-8000-000000000001','cash-owner@local.invalid'),('ca100000-0000-4000-8000-000000000002','cash-worker@local.invalid'),('ca100000-0000-4000-8000-000000000003','cash-foreign@local.invalid');
alter table auth.users enable trigger on_auth_user_created;
insert into public.companies(id,name) values('ca200000-0000-4000-8000-000000000001','Synthetic cash contractor'),('ca200000-0000-4000-8000-000000000002','Other synthetic cash contractor');
insert into public.profiles(id,company_id,role) values ('ca100000-0000-4000-8000-000000000001','ca200000-0000-4000-8000-000000000001','owner'),('ca100000-0000-4000-8000-000000000002','ca200000-0000-4000-8000-000000000001','employee'),('ca100000-0000-4000-8000-000000000003','ca200000-0000-4000-8000-000000000002','owner');
insert into public.plaid_connections(id,company_id,item_id,access_token_ciphertext,token_iv,token_auth_tag) values('ca600000-0000-4000-8000-000000000001','ca200000-0000-4000-8000-000000000001','synthetic-cash-item','NOT-A-TOKEN','synthetic','synthetic');
insert into public.plaid_accounts(id,company_id,connection_id,plaid_account_id,name) values('ca610000-0000-4000-8000-000000000001','ca200000-0000-4000-8000-000000000001','ca600000-0000-4000-8000-000000000001','synthetic-cash-account','Synthetic bank');
insert into public.plaid_transactions(id,company_id,connection_id,account_id,plaid_transaction_id,plaid_account_id,transaction_date,name,plaid_amount,cash_amount) values('ca620000-0000-4000-8000-000000000001','ca200000-0000-4000-8000-000000000001','ca600000-0000-4000-8000-000000000001','ca610000-0000-4000-8000-000000000001','synthetic-cash-tax','synthetic-cash-account','2026-10-16','Synthetic tax debit',5,-5);
insert into public.plaid_transactions(id,company_id,connection_id,account_id,plaid_transaction_id,plaid_account_id,transaction_date,name,plaid_amount,cash_amount) values('ca620000-0000-4000-8000-000000000002','ca200000-0000-4000-8000-000000000001','ca600000-0000-4000-8000-000000000001','ca610000-0000-4000-8000-000000000001','synthetic-cash-receipt','synthetic-cash-account','2026-10-16','Synthetic expense debit',12,-12);
insert into public.company_documents(id,company_id,title,document_type,storage_path) values('ca630000-0000-4000-8000-000000000001','ca200000-0000-4000-8000-000000000001','Synthetic receipt only','receipt','synthetic/local-only-receipt.pdf');
insert into public.projects(id,company_id,job_number,name,status) values('ca640000-0000-4000-8000-000000000001','ca200000-0000-4000-8000-000000000001','SYN-CASH','Synthetic cash job','active');
insert into public.cost_codes(id,company_id,code,name,cost_type) values('ca650000-0000-4000-8000-000000000001','ca200000-0000-4000-8000-000000000001','MAT','Synthetic material','material');
insert into public.vendors(id,company_id,name) values('ca660000-0000-4000-8000-000000000001','ca200000-0000-4000-8000-000000000001','Synthetic supplier');
insert into public.vendor_bills(id,company_id,project_id,vendor_id,vendor_bill_number) values('ca670000-0000-4000-8000-000000000001','ca200000-0000-4000-8000-000000000001','ca640000-0000-4000-8000-000000000001','ca660000-0000-4000-8000-000000000001','SYN-CASH-BILL');
insert into public.vendor_bill_lines(company_id,vendor_bill_id,cost_code_id,description,quantity,unit_cost,subtotal,sales_tax,total_cost) values('ca200000-0000-4000-8000-000000000001','ca670000-0000-4000-8000-000000000001','ca650000-0000-4000-8000-000000000001','Synthetic posted bill',1,50,50,0,50);
update public.vendor_bills set status='posted' where id='ca670000-0000-4000-8000-000000000001';
insert into public.overhead_items(id,company_id,name,category,business_use_percent) values('ca680000-0000-4000-8000-000000000001','ca200000-0000-4000-8000-000000000001','Synthetic zero-use plan','Other',0);
create temp table cash_results(key text primary key,value jsonb);grant all on cash_results to authenticated;
create function pg_temp.cash(n integer,c text,p jsonb) returns jsonb language sql as $$select public.carez_cash_command_v1(('ca500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,c,p)$$;
select set_config('request.jwt.claim.sub','ca100000-0000-4000-8000-000000000001',true);set local role authenticated;
insert into cash_results values('account',pg_temp.cash(1,'add_account','{"name":"Synthetic petty cash","account_type":"cash"}'));
select extensions.is(pg_temp.cash(1,'add_account','{"name":"Synthetic petty cash","account_type":"cash"}'),(select value from cash_results where key='account'),'account retry returns its confirmed receipt');
select extensions.ok((select not include_with_connected_banks from public.company_cash_accounts where id=(select (value->>'id')::uuid from cash_results where key='account')),'manual cash is not silently added on top of connected banking');
insert into cash_results values('balance',pg_temp.cash(2,'record_balance',jsonb_build_object('cash_account_id',(select value->>'id' from cash_results where key='account'),'balance_date','2026-10-16','balance','-25.01')));
select extensions.is((select balance from public.company_cash_balance_snapshots where id=(select (value->>'id')::uuid from cash_results where key='balance')),-25.01::numeric,'signed recorded balances remain signed');
select extensions.throws_like($$select pg_temp.cash(3,'record_balance',jsonb_build_object('cash_account_id',(select value->>'id' from cash_results where key='account'),'balance_date','2026-10-16','balance','9'))$$,'%already recorded or changed%','unloaded existing balance cannot be overwritten');
insert into cash_results values('correction',pg_temp.cash(3,'record_balance',jsonb_build_object('cash_account_id',(select value->>'id' from cash_results where key='account'),'balance_date','2026-10-16','balance','0','expected_snapshot_id',(select value->>'id' from cash_results where key='balance'),'expected_revision','0','notes','Synthetic reviewed correction')));
select extensions.ok((select (value#>>'{before,balance}')::numeric=-25.01 and (value#>>'{after,balance}')::numeric=0 and (value#>>'{after,revision}')::integer=1 from cash_results where key='correction'),'correction keeps audited before/after and permits genuine zero');
select extensions.throws_like($$select pg_temp.cash(4,'record_balance',jsonb_build_object('cash_account_id',(select value->>'id' from cash_results where key='account'),'balance_date','2026-10-16','balance','8','expected_snapshot_id',(select value->>'id' from cash_results where key='balance'),'expected_revision','0','notes','stale'))$$,'%already recorded or changed%','stale correction is rejected');
select extensions.throws_like($$select pg_temp.cash(4,'record_balance',jsonb_build_object('cash_account_id',(select value->>'id' from cash_results where key='account'),'balance_date','2026-10-17','balance','NaN'))$$,'%must be finite%','nonfinite balance rejected');
insert into cash_results values('expense',pg_temp.cash(4,'add_expense','{"description":"Synthetic personal allocation","expense_date":"2026-10-16","category":"Other","subtotal":"100","sales_tax":"10","business_use_percent":"0","payment_status":"unpaid","cash_source":"company_account"}'));
select extensions.ok((select total_amount=110 and business_expense_amount=0 and business_use_percent=0 from public.company_expenses where id=(select (value->>'id')::uuid from cash_results where key='expense')),'expense derives full obligation separately from explicit zero business portion');
insert into cash_results values('plan-zero',pg_temp.cash(30,'add_expense','{"description":"Synthetic recorded plan basis","overhead_item_id":"ca680000-0000-4000-8000-000000000001","expense_date":"2026-10-16","subtotal":"10","sales_tax":"0","payment_status":"unpaid","cash_source":"personal"}'));
select extensions.ok((select business_use_percent=0 and business_expense_amount=0 from public.company_expenses where id=(select (value->>'id')::uuid from cash_results where key='plan-zero')),'blank percentage inherits a known selected plan rate, preserving explicit zero');
select extensions.is((select unpaid_company_expense_obligations from public.company_expense_summary where company_id='ca200000-0000-4000-8000-000000000001'),110::numeric,'unpaid cash obligation uses full amount, not deductible portion');
select extensions.throws_like($$select pg_temp.cash(5,'add_expense','{"description":"bad","expense_date":"2026-10-16","category":"Other","subtotal":"0","sales_tax":"0","payment_status":"paid","cash_source":"company_account","paid_date":"2026-10-16"}')$$,'%business_use_percent is required%','missing business basis is not defaulted to one hundred');
select extensions.lives_ok($$select pg_temp.cash(5,'pay_expense',jsonb_build_object('expense_id',(select value->>'id' from cash_results where key='expense'),'expected_updated_at',(select updated_at from public.company_expenses where id=(select (value->>'id')::uuid from cash_results where key='expense')),'paid_date','2026-10-17','payment_method','card'))$$,'pay transition confirms one scoped unpaid expense');
select extensions.ok((select payment_status='paid' and paid_date='2026-10-17' from public.company_expenses where id=(select (value->>'id')::uuid from cash_results where key='expense')),'paid facts reopen without changing recorded expense basis');
select extensions.throws_like($$select pg_temp.cash(6,'pay_expense',jsonb_build_object('expense_id',(select value->>'id' from cash_results where key='expense'),'expected_updated_at',(select updated_at from public.company_expenses where id=(select (value->>'id')::uuid from cash_results where key='expense')),'paid_date','2026-10-17','payment_method','card'))$$,'%Only unpaid expenses%','different request cannot pay an expense again');
insert into cash_results values('reserve',pg_temp.cash(6,'add_reserve','{"name":"Synthetic payroll protection","reserve_type":"payroll_tax","amount":"50"}'));
select extensions.is((select amount from public.company_cash_reserves where id=(select (value->>'id')::uuid from cash_results where key='reserve')),50::numeric,'reserve amount is saved independently from expense and cash balances');
select extensions.lives_ok($$select pg_temp.cash(7,'release_reserve',jsonb_build_object('reserve_id',(select value->>'id' from cash_results where key='reserve'),'expected_updated_at',(select updated_at from public.company_cash_reserves where id=(select (value->>'id')::uuid from cash_results where key='reserve'))))$$,'reserve releases using current revision');
select extensions.ok((select not active from public.company_cash_reserves where id=(select (value->>'id')::uuid from cash_results where key='reserve')),'released reserve remains as history');
select extensions.throws_like($$select pg_temp.cash(8,'record_remittance','{"tax_type":"payroll_tax","payment_date":"2026-10-16","amount":"5"}')$$,'%valid tax type%','remittance vocabulary is distinct from reserve vocabulary');
insert into cash_results values('tax',pg_temp.cash(8,'record_remittance','{"tax_type":"sales_tax","payment_date":"2026-10-16","amount":"5"}'));
select extensions.is((select count(*) from public.carez_active_tax_remittances_v1 where company_id='ca200000-0000-4000-8000-000000000001'),1::bigint,'recorded remittance is included in existing active source set');
select extensions.lives_ok($$select pg_temp.cash(9,'reverse_remittance',jsonb_build_object('remittance_id',(select value->>'id' from cash_results where key='tax'),'expected_created_at',(select created_at from public.company_tax_remittances where id=(select (value->>'id')::uuid from cash_results where key='tax')),'reversal_reason','Synthetic duplicate entry'))$$,'manual reversal is explicit and audited');
select extensions.ok((select reversed_at is not null and reversed_by='ca100000-0000-4000-8000-000000000001' and amount=5 from public.company_tax_remittances where id=(select (value->>'id')::uuid from cash_results where key='tax')),'original tax payment is preserved with reversal facts');
select extensions.is((select count(*) from public.carez_active_tax_remittances_v1 where company_id='ca200000-0000-4000-8000-000000000001'),0::bigint,'reversed remittance no longer reduces tax protection');
insert into cash_results values('bank-tax',public.carez_reconcile_bank_to_tax_v2('ca500000-0000-4000-8000-000000000010','ca620000-0000-4000-8000-000000000001','sales_tax'));
select extensions.throws_like($$select pg_temp.cash(11,'reverse_remittance',jsonb_build_object('remittance_id',(select value->>'id' from cash_results where key='bank-tax'),'expected_created_at',(select created_at from public.company_tax_remittances where id=(select (value->>'id')::uuid from cash_results where key='bank-tax')),'reversal_reason','Synthetic'))$$,'%supported reconciliation reversal%','bank-linked reversal cannot orphan its reconciliation link');
select extensions.ok((select review_status='matched' and matched_entity_type='tax_remittance' from public.plaid_transactions where id='ca620000-0000-4000-8000-000000000001'),'existing governed bank writer still persists after raw table grants are removed');
insert into cash_results values('receipt-expense',public.carez_reconcile_document_receipt_to_company_expense_v2('ca500000-0000-4000-8000-000000000020','ca630000-0000-4000-8000-000000000001','ca620000-0000-4000-8000-000000000002',null,'Other',0,'Synthetic zero-use receipt'));
select extensions.ok((select total_amount=12 and business_use_percent=0 and business_expense_amount=0 and bank_transaction_id='ca620000-0000-4000-8000-000000000002' from public.company_expenses where id=(select (value->>'id')::uuid from cash_results where key='receipt-expense')),'receipt reconciliation preserves full cash amount and genuine zero business use');
select extensions.is(public.carez_reconcile_document_receipt_to_company_expense_v2('ca500000-0000-4000-8000-000000000020','ca630000-0000-4000-8000-000000000001','ca620000-0000-4000-8000-000000000002',null,'Other',0,'Synthetic zero-use receipt'),(select value from cash_results where key='receipt-expense'),'receipt retry does not duplicate expense or receipt association');
insert into cash_results values('vendor-payment',public.carez_record_vendor_bill_payment_v2('ca500000-0000-4000-8000-000000000021','ca670000-0000-4000-8000-000000000001','2026-10-16',20,'ach','Synthetic',2,'Synthetic vendor fee'));
select extensions.ok((select total_amount=2 and payment_status='paid' from public.company_expenses where source_type='vendor_payment_fee' and source_id=(select (value->>'id')::uuid from cash_results where key='vendor-payment')),'governed vendor payment still creates its coupled fee');
select extensions.throws_like($$select pg_temp.cash(22,'void_expense',jsonb_build_object('expense_id',(select id from public.company_expenses where source_type='vendor_payment_fee' and source_id=(select (value->>'id')::uuid from cash_results where key='vendor-payment')),'expected_updated_at',(select updated_at from public.company_expenses where source_type='vendor_payment_fee' and source_id=(select (value->>'id')::uuid from cash_results where key='vendor-payment'))))$$,'%originating bank or vendor-payment workflow%','generic void cannot decouple a vendor-payment fee');
select extensions.lives_ok($$select public.carez_void_vendor_payment_v2('ca500000-0000-4000-8000-000000000022',(select (value->>'id')::uuid from cash_results where key='vendor-payment'))$$,'vendor reversal uses its governed originating workflow');
select extensions.ok((select payment_status='void' from public.company_expenses where source_type='vendor_payment_fee' and source_id=(select (value->>'id')::uuid from cash_results where key='vendor-payment')),'vendor reversal voids its coupled expense exactly once');
select extensions.throws_like($$delete from public.company_tax_remittances$$,'%permission denied%','raw remittance deletion cannot erase audit history');
select extensions.throws_like($$update public.company_expenses set payment_status='void'$$,'%permission denied%','raw expense changes cannot bypass command state checks');
reset role;
create function pg_temp.fail_cash_insert() returns trigger language plpgsql as $$begin raise exception 'Synthetic late cash failure';end$$;
create trigger synthetic_cash_failure before insert on public.company_cash_reserves for each row execute function pg_temp.fail_cash_insert();
set local role authenticated;
select extensions.throws_like($$select pg_temp.cash(11,'add_reserve','{"name":"late failure","reserve_type":"other","amount":"1"}')$$,'%Synthetic late cash failure%','downstream save failure reaches caller');
select extensions.ok(not exists(select 1 from public.financial_command_requests where request_id='ca500000-0000-4000-8000-000000000011'),'failed write rolls back its request receipt');
reset role;drop trigger synthetic_cash_failure on public.company_cash_reserves;
select set_config('request.jwt.claim.sub','ca100000-0000-4000-8000-000000000003',true);set local role authenticated;
select extensions.throws_like($$select pg_temp.cash(12,'record_balance',jsonb_build_object('cash_account_id',(select value->>'id' from cash_results where key='account'),'balance_date','2026-10-17','balance','5'))$$,'%unavailable%','foreign account is not writable');
reset role;select set_config('request.jwt.claim.sub','ca100000-0000-4000-8000-000000000002',true);set local role authenticated;
select extensions.throws_like($$select pg_temp.cash(13,'add_account','{"name":"denied","account_type":"cash"}')$$,'%Owner or office authority%','employee cannot post cash administration');
reset role;set local role anon;
select extensions.throws_like($$select pg_temp.cash(14,'add_account','{"name":"denied","account_type":"cash"}')$$,'%permission denied%','anonymous command denied');
reset role;select * from extensions.finish();
rollback;
